// ==== eventos.js ====
/* static/js/core/eventos.js
============================================
HELPERS GLOBAIS — Padrão 2099
============================================ */

// Atalhos de querySelector
window.$  = (sel, ctx) => (ctx || document).querySelector(sel);
window.$$ = (sel, ctx) => Array.from((ctx || document).querySelectorAll(sel));

// Delegação de eventos (evita listeners repetidos)
window.delegar = (elemento, evento, seletor, callback) => {
    elemento.addEventListener(evento, (e) => {
        const alvo = e.target.closest(seletor);
        if (alvo) callback(e, alvo);
    });
};

// Debounce (útil pra inputs)
window.debounce = (fn, delay) => {
    let timer;
    return (...args) => {
        clearTimeout(timer);
        timer = setTimeout(() => fn(...args), delay || 300);
    };
};

// ==== notificacoes.js ====
/* static/js/components/notificacoes.js
============================================
SISTEMA DE NOTIFICAÇÕES - GLOBAL
============================================ */

if (window.Notificacao) {
    console.warn("Notificacao já existe - evitando duplicação");
} else {

    window.Notificacao = {

        _container: null,

        _criarContainer() {
            if (this._container) return this._container;
            this._container = document.createElement('div');
            this._container.className = 'notificacao-container';
            this._container.setAttribute('aria-live', 'polite');
            document.body.appendChild(this._container);
            return this._container;
        },

        _criarItem(mensagem, tipo) {
            const icones = { sucesso: '✅', erro: '❌', aviso: '⚠️' };
            const item = document.createElement('div');
            item.className = `notificacao-item ${tipo}`;
            item.innerHTML = `
                <span class="notificacao-icone">${icones[tipo] || 'ℹ️'}</span>
                <span class="notificacao-mensagem">${mensagem}</span>
                <button class="notificacao-fechar" aria-label="Fechar">✕</button>
            `;
            item.querySelector('.notificacao-fechar').addEventListener('click', () => {
                item.classList.add('saindo');
                setTimeout(() => item.remove(), 300);
            });
            return item;
        },

        _mostrar(mensagem, tipo, duracao = 3000) {
            const container = this._criarContainer();
            const item = this._criarItem(mensagem, tipo);
            container.appendChild(item);
            if (duracao > 0) {
                setTimeout(() => {
                    if (!item.parentElement) return;
                    item.classList.add('saindo');
                    setTimeout(() => item.remove(), 300);
                }, duracao);
            }
            return item;
        },

        sucesso(m, d = 3000) { return window.Notificacao._mostrar(m, 'sucesso', d); },
        erro(m, d = 5000)    { return window.Notificacao._mostrar(m, 'erro', d); },
        aviso(m, d = 4000)   { return window.Notificacao._mostrar(m, 'aviso', d); },

        api(response, duracao) {
            if (!response) return this.erro('Erro desconhecido', duracao);
            const tipo = response.success ? 'sucesso' : 'erro';
            const msg  = response.message || response.error || 'Sem mensagem';
            return this[tipo](msg, duracao);
        }
    };
}

// ==== mockup.js ====
/* static/js/components/mockup.js
   Rascunho ao vivo. NUNCA salva. Usa window.ESCALA (injetado pelo Jinja).
   Chamado a cada input/change do form via Mockup.aplicar(config_final).

   REGRA DE FUNDO (igual backend):
     - Se user escolheu cor (diferente do default) → cor dele vence.
     - Senão → gradiente do template (se houver) ou default.
*/
(function () {
    'use strict';

    window.Mockup = {
        aplicar: function (configFinal) {
            const tela = document.getElementById('mockupTela');
            if (!tela) return;
            const E = window.ESCALA;
            if (!E) { console.warn('window.ESCALA não definido'); return; }

            const cfg = configFinal || {};
            const c = cfg.cores      || {};
            const t = cfg.tipografia || {};
            const l = cfg.layout     || {};
            const e = cfg.efeitos    || {};

            const fator = (E.FATOR_PREVIEW || 0.65);
            const px = (valor) => Math.round(valor * fator) + 'px';

            const set = (k, v) => {
                if (v != null) tela.style.setProperty(k, v);
            };

            // Cores
            set('--perfil-cor-primaria',   c.primaria   || E.DEFAULTS.primaria);
            set('--perfil-cor-secundaria', c.secundaria || E.DEFAULTS.secundaria);
            set('--perfil-cor-fundo',      c.fundo      || E.DEFAULTS.fundo);
            set('--perfil-cor-texto',      c.texto      || E.DEFAULTS.texto);

            // FUNDO EFETIVO (mesma regra do backend)
            const fundoUser = c.fundo || E.DEFAULTS.fundo;
            const fundoEfetivo = (fundoUser !== E.DEFAULTS.fundo)
                ? fundoUser
                : (e.background || fundoUser);
            set('--perfil-background-efetivo', fundoEfetivo);

            // Tipografia
            set('--perfil-fonte',
                E.FONTE[t.fonte || E.DEFAULTS.fonte] || E.FONTE.padrao);
            set('--perfil-raio-link',
                px(E.RAIO[t.estilo_botao || E.DEFAULTS.estilo] || 12));

            // Layout (tudo multiplicado pelo FATOR_PREVIEW)
            set('--perfil-foto-tamanho',
                px(E.FOTO[l.tamanho_foto || E.DEFAULTS.tamanho_foto] || 128));
            set('--perfil-link-tamanho',
                px(E.LINK[l.tamanho_link || E.DEFAULTS.tamanho_link] || 56));
            set('--perfil-gap',
                px(E.GAP[l.espacamento_links || E.DEFAULTS.gap] || 14));
            set('--perfil-borda-tamanho',
                px(E.BORDA[l.borda_link || E.DEFAULTS.borda] || 3));

            // Hover
            const hover = E.HOVER[e.hover_efeito || E.DEFAULTS.hover] || E.HOVER.subir;
            set('--perfil-hover-transform', hover.transform);
            set('--perfil-hover-brilho',    hover.filter);

            // Animação
            const anim = E.ANIMACAO[e.animacao_entrada || E.DEFAULTS.animacao] || 'fade';
            tela.classList.remove('anim-fade', 'anim-slide', 'anim-scale', 'anim-nenhuma');
            if (anim) tela.classList.add('anim-' + anim);
        },

        // Identidade (não é tema — não passa por config)
        setNome: function (txt) {
            const el = document.getElementById('mockupNome');
            if (el) el.textContent = txt || 'Seu nome';
        },
        setBio: function (txt) {
            const el = document.getElementById('mockupBio');
            if (el) el.textContent = txt || 'Sua bio aparece aqui...';
        },
        setFoto: function (src) {
            const el = document.getElementById('mockupFoto');
            if (!el) return;
            if (src) {
                const sel = document.getElementById('foto_posicao');
                const pos = sel ? sel.value : 'top';
                el.innerHTML = '<img src="' + src + '" alt="Foto" style="object-position: center ' + pos + ';">';
            } else {
                el.innerHTML = '<i class="fas fa-user"></i>';
            }
        },
        setFotoPosicao: function (pos) {
            const img = document.querySelector('#mockupFoto img');
            if (img) img.style.objectPosition = 'center ' + (pos || 'top');
        },
    };

    console.log('✅ Mockup carregado (unificado, cor do user vence gradiente)');
})();

// ==== modal.js ====
/* static/js/components/modal.js
============================================
SISTEMA DE MODAL — Global
============================================ */

(function() {
    'use strict';

    // Fecha modal no X ou no "Cancelar"
    document.addEventListener('click', function(e) {
        const btnFechar = e.target.closest('[data-modal-fechar]');
        if (btnFechar) {
            e.preventDefault();
            const modal = btnFechar.closest('[data-modal]');
            if (modal) fecharModal(modal);
            return;
        }

        // Clica fora (overlay) fecha
        const overlay = e.target.closest('[data-modal]');
        if (overlay && e.target === overlay) {
            fecharModal(overlay);
        }
    });

    // ESC fecha o modal visível
    document.addEventListener('keydown', function(e) {
        if (e.key !== 'Escape') return;
        const modais = document.querySelectorAll('[data-modal]');
        modais.forEach(m => fecharModal(m));
    });

    function fecharModal(modal) {
        modal.style.animation = 'modalFadeOut 0.15s ease forwards';
        setTimeout(() => {
            modal.remove();
            document.body.style.overflow = '';
        }, 150);
    }

    // Quando o HTMX injeta um modal novo, desbloqueia o scroll
    document.body.addEventListener('htmx:afterSwap', function(e) {
        if (e.detail.target.querySelector('[data-modal]') ||
            e.detail.target.matches('[data-modal]')) {
            document.body.style.overflow = 'hidden';
        }
    });

})();

// ==== sidebar.js ====
/* static/js/components/sidebar.js
============================================
SIDEBAR — Menu mobile
============================================ */

(function() {
    'use strict';

    const menuToggle  = document.getElementById('menuToggle');
    const menuClose   = document.getElementById('menuClose');
    const overlay     = document.getElementById('sidebarOverlay');
    const sidebar     = document.getElementById('mainSidebar');

    if (!sidebar) return;

    function abrir() {
        sidebar.classList.add('active');
        overlay?.classList.add('active');
        document.body.style.overflow = 'hidden';
    }

    function fechar() {
        sidebar.classList.remove('active');
        overlay?.classList.remove('active');
        document.body.style.overflow = '';
    }

    menuToggle?.addEventListener('click', abrir);
    menuClose?.addEventListener('click', fechar);
    overlay?.addEventListener('click', fechar);

    // Fecha ao clicar num link da sidebar (mobile)
    sidebar.querySelectorAll('.sidebar-nav a').forEach(link => {
        link.addEventListener('click', () => {
            if (window.innerWidth <= 992) fechar();
        });
    });

})();

// ==== tema.js ====
/* static/js/components/tema.js
============================================
TEMA claro/escuro — Global
============================================ */

(function() {
    'use strict';

    const STORAGE_KEY = 'meulinks-tema';
    const html = document.documentElement;

    // ─── Detecta tema salvo (ou preferência do sistema) ───
    function obterTemaInicial() {
        const salvo = localStorage.getItem(STORAGE_KEY);
        if (salvo === 'light' || salvo === 'dark') return salvo;
        return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }

    function aplicarTema(tema) {
        html.setAttribute('data-theme', tema);
        localStorage.setItem(STORAGE_KEY, tema);

        // Atualiza o ícone do botão (se existir)
        const icone = document.querySelector('[data-toggle-tema] i');
        if (icone) {
            icone.className = tema === 'dark' ? 'fas fa-moon' : 'fas fa-sun';
        }
    }

    // ─── Aplica na hora (evita flash) ───
    aplicarTema(obterTemaInicial());

    // ─── Botão de toggle ───
    document.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-toggle-tema]');
        if (!btn) return;

        const atual = html.getAttribute('data-theme');
        const novo = atual === 'dark' ? 'light' : 'dark';
        aplicarTema(novo);

        // Notificação opcional
        if (window.Notificacao) {
            Notificacao.sucesso(novo === 'dark' ? 'Modo escuro ativado 🌙' : 'Modo claro ativado ☀️');
        }
    });

    // ─── Detecta mudança do sistema (se o usuário não escolheu) ───
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    mq.addEventListener('change', (e) => {
        if (!localStorage.getItem(STORAGE_KEY)) {
            aplicarTema(e.matches ? 'dark' : 'light');
        }
    });
})();

